# ── Bytecode introspection ────────────────────────────────────────────────────

def annotated_disassembly(fn) -> str:
    buf = io.StringIO()
    dis.dis(fn, file=buf)
    return buf.getvalue()

# ── dis - decodes bytecodes from a .pyc or .pyo file ──────────────────────────

PYTHON_BYTECODES = {
    'dis': dis.dis,
    'load_const': load_const,
    'load_name': load_name,
    'build_class': build_class,
}

for name, fn in PYTHON_BYTECODES.items():
    print(f"Disassembling {name}:")
    print(annotated_disassembly(fn))
    print()


# ── Code Objects ──────────────────────────────────────────────────────────────

SOURCE_CODE = textwrap.dedent("""
    def foo(x):
        x += 1
    del x
    """).strip()
print("\nCode object:")
CO = compile(SOURCE_CODE, filename="<demo>", mode="exec")

print(CO.co_filename)
print(CO.co_firstlineno)
print(CO.co_consts)
print(CO.co_names)
print(CO.co_varnames)

if CO.co_argcount == 0:
    print("No positional arguments.")
elif CO.co_argcount == 1:
    print("One positional argument:", CO.co_varnames[0])
else:
    print("Positional arguments:", ", ".join(CO.co_varnames[:CO.co_argcount]))
print(CO.co_freevars)
print(CO.co_cellvars)

# ── ctypes ────────────────────────────────────────────────────────────────────

fn_ptr = ctypes.cast(CO.co_code, ctypes.py_object).value
function_type = ctypes.c_functionptr.argtypes[0]
func = function_type.from_address(ctypes.addressof(fn_ptr))

args = [ctypes.c_int(), ctypes.c_int()]
result = func(*args)
print(result)

# ── Struct ───────────────────────────────────────────────────────────────────

STRUCT_BYTES = b"\x01\x02\x03\x04\x05\x06\x07\x08"
struct.unpack("<HHH", STRUCT_BYTES)

with struct.Struct(">HHH") as s:
    unpacked = list(s.iter_unpack(STRUCT_BYTES))
    print(unpacked)


